/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type TranscriptRole = "user" | "assistant" | "system"

export interface TranscriptSegment {
  id: string
  role: TranscriptRole
  /** Speaker label override, for example "Noor". */
  speaker?: string
  /** Settled text. */
  text: string
  /** Words the recognizer has not settled yet, appended in a lighter gray. */
  interim?: string
  /** Milliseconds from the start of the session. Shown as m:ss. */
  at?: number
  /** `voice` (spoken, the default) or `text` (typed while in text mode). */
  channel?: "voice" | "text"
  /** Barge-in: the assistant was cut off. `text` is what was spoken before the cut. */
  interrupted?: boolean
  /** The rest of the reply that was never spoken, shown struck after the cut. */
  unspoken?: string
  /** Still being spoken or streamed. Shows the streaming caret. */
  live?: boolean
}

export interface TranscriptProps extends Omit<React.ComponentProps<"div">, "children"> {
  segments: TranscriptSegment[]
  /** Label for user segments. Default "You". */
  userLabel?: string
  /** Label for assistant segments. Default "Assistant". */
  assistantLabel?: string
  /** Stick to the bottom while new speech arrives. Any upward scroll releases it. Default true. */
  follow?: boolean
  /** Makes timestamps buttons that seek playback to that moment, in ms. */
  onSeek?: (ms: number) => void
  /** The segment being played back. Highlighted and kept in view. */
  activeId?: string
  /** Default true. */
  showTimestamps?: boolean
  /**
   * `stacked`: speaker and time above the text, for live conversation. `inline`: a time and
   * speaker gutter at the start of every line, dense, for meeting capture and playback.
   */
  layout?: "stacked" | "inline"
  /** Shown while there are no segments. */
  empty?: React.ReactNode
  /** Accessible name of the transcript. Default "Transcript". */
  label?: string
  /** Read finished assistant segments to screen readers, once, never word by word. Default true. */
  announce?: boolean
}

interface Group {
  key: string
  role: TranscriptRole
  speaker: string
  segments: TranscriptSegment[]
}

function groupSegments(
  segments: TranscriptSegment[],
  labels: { user: string; assistant: string },
): Group[] {
  const groups: Group[] = []
  for (const segment of segments) {
    const speaker =
      segment.speaker ??
      (segment.role === "user" ? labels.user : segment.role === "assistant" ? labels.assistant : "")
    const last = groups[groups.length - 1]
    if (
      last &&
      segment.role !== "system" &&
      last.role === segment.role &&
      last.speaker === speaker
    ) {
      last.segments.push(segment)
    } else {
      groups.push({ key: segment.id, role: segment.role, speaker, segments: [segment] })
    }
  }
  return groups
}

/* -------------------------------------------------------------------------------------------------
 * Body
 * -----------------------------------------------------------------------------------------------*/

interface BodyProps {
  segments: TranscriptSegment[]
  groups: Group[]
  layout: "stacked" | "inline"
  showTimestamps: boolean
  onSeek?: (ms: number) => void
  activeId?: string
  empty?: React.ReactNode
  announce: boolean
  announceFn?: (text: string) => void
}

/** Announces finished assistant segments through the conversation's live region. */
function useAnnounce(
  segments: TranscriptSegment[],
  enabled: boolean,
  announce?: (t: string) => void,
) {
  const seen = React.useRef<Set<string> | null>(null)
  React.useEffect(() => {
    // History present on mount is not read out.
    if (seen.current === null) {
      seen.current = new Set(segments.filter((s) => !s.live && !s.interim).map((s) => s.id))
      return
    }
    if (!enabled || !announce) return
    for (const s of segments) {
      if (s.role !== "assistant" || s.live || s.interim || seen.current.has(s.id)) continue
      seen.current.add(s.id)
      const text = s.text.trim()
      if (text) announce(s.interrupted ? `${text} (interrupted)` : text)
    }
  }, [segments, enabled, announce])
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

