/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function formatTime(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = String(total % 60).padStart(2, "0")
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${s}` : `${m}:${s}`
}

function spokenTime(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000))
  const m = Math.floor(total / 60)
  const s = total % 60
  const parts: string[] = []
  if (m) parts.push(`${m} ${m === 1 ? "minute" : "minutes"}`)
  parts.push(`${s} ${s === 1 ? "second" : "seconds"}`)
  return parts.join(" ")
}

/* -------------------------------------------------------------------------------------------------
 * Parts
 * -----------------------------------------------------------------------------------------------*/

function Timestamp({
  ms,
  speaker,
  onSeek,
  className,
}: {
  ms: number
  speaker: string
  onSeek?: (ms: number) => void
  className?: string
}) {
  const text = formatTime(ms)
  if (!onSeek) {
    return (
      <time
        dateTime={`PT${Math.floor(ms / 1000)}S`}
        className={cn("text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums", className)}
      >
        {text}
      </time>
    )
  }
  return (
    <button
      type="button"
      onClick={() => onSeek(ms)}
      // Starts with the time it shows, so voice control can say "0:02".
      aria-label={`${text}, play from ${spokenTime(ms)}${speaker ? `, ${speaker}` : ""}`}
      data-slot="transcript-seek"
      className={cn(
        "chatcn-focus text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) rounded-(--chatcn-radius-xs) -mx-1 px-1 tabular-nums",
        "hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) transition-colors duration-150",
        "relative pointer-coarse:after:absolute pointer-coarse:after:-inset-2 pointer-coarse:after:content-['']",
        className,
      )}
    >
      {text}
    </button>
  )
}

