const KeyboardIcon: Icon = /* @__PURE__ */ createIcon("keyboard", iconNode2)

type StreamingCaretStatus = "streaming" | "waiting" | "done"

interface StreamingCaretProps extends Omit<React.ComponentProps<"span">, "children"> {
  /**
   * `streaming` is solid, `waiting` blinks slowly, `done` removes the caret. Defaults to
   * `streaming`.
   */
  status?: StreamingCaretStatus
  /**
   * Pass the streamed text (or anything that changes with each token). While it keeps changing
   * the caret stays solid; once it holds still for `idleMs` the caret starts to blink.
   */
  activity?: unknown
  /** Quiet time before the caret switches to blinking. Defaults to 600 ms. */
  idleMs?: number
}

/**
 * The signature mark: a small rounded square that means "the model is writing here". It sits on
 * the text baseline at 0.55em, so it scales with whatever text it follows. Solid while tokens flow,
 * a slow 1.2 s blink only while waiting, gone when done. Static under reduced motion.
 */
function StreamingCaret({
  status = "streaming",
  activity,
  idleMs = 600,
  className,
  ...props
}: StreamingCaretProps) {
  const [idle, setIdle] = React.useState(false)
  const tracking = activity !== undefined && status === "streaming"

  React.useEffect(() => {
    if (!tracking) return
    setIdle(false)
    const id = window.setTimeout(() => setIdle(true), idleMs)
    return () => window.clearTimeout(id)
  }, [activity, tracking, idleMs])

  if (status === "done") return null
  const blinking = status === "waiting" || (tracking && idle)

  return (
    <span
      aria-hidden="true"
      data-slot="streaming-caret"
      data-caret-state={blinking ? "waiting" : "streaming"}
      className={cn(
        "bg-(color:--chatcn-accent) ms-0.5 inline-block size-[0.55em] translate-y-[0.04em] rounded-[0.12em] align-baseline forced-colors:bg-[CanvasText]",
        blinking &&
          "animate-[chatcn-caret-blink_1.2s_steps(1,end)_infinite] motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  )
}

/** The text of one segment: settled words, interim words, the cut and the unspoken rest. */
function SegmentText({ segment }: { segment: TranscriptSegment }) {
  const typed = segment.channel === "text"
  return (
    <>
      {typed ? (
        <span className="me-1.5 inline-flex translate-y-[0.12em] align-baseline">
          <KeyboardIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-[1em]" />
          <span className="sr-only">Typed: </span>
        </span>
      ) : null}
      {segment.text}
      {segment.interim ? (
        <span data-slot="transcript-interim" className="text-(color:--chatcn-fg-subtle)">
          {segment.text && !/\s$/.test(segment.text) ? " " : ""}
          {segment.interim}
        </span>
      ) : null}
      {segment.interrupted ? (
        <>
          {/* The cut: a hairline at the exact point the user spoke over the reply. */}
          <span
            aria-hidden="true"
            data-slot="transcript-cut"
            className="bg-(color:--chatcn-accent) mx-1 inline-block h-[1.05em] w-px translate-y-[0.18em] align-baseline"
          />
          {segment.unspoken ? (
            <span
              data-slot="transcript-unspoken"
              className="text-(color:--chatcn-fg-subtle) decoration-(color:--chatcn-border-strong) line-through"
            >
              <span className="sr-only">Not spoken: </span>
              {segment.unspoken}
            </span>
          ) : null}
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ms-2 font-medium whitespace-nowrap">
            Interrupted
          </span>
        </>
      ) : null}
      {segment.live ? (
        <StreamingCaret activity={`${segment.text}${segment.interim ?? ""}`} />
      ) : null}
    </>
  )
}

function TranscriptBody({
  segments,
  groups,
  layout,
  showTimestamps,
  onSeek,
  activeId,
  empty,
  announce,
  announceFn,
}: BodyProps) {
  useAnnounce(segments, announce, announceFn)

  if (segments.length === 0) {
    return (
      <div
        data-slot="transcript-empty"
        className="flex min-h-40 flex-1 flex-col items-center justify-center gap-2 px-6 text-center"
      >
        {empty ?? (
          <>
            <AudioLinesIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-5" />
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) max-w-60 text-pretty">
              What you and the assistant say appears here as you talk.
            </p>
          </>
        )}
      </div>
    )
  }

  if (layout === "inline") {
    return (
      <div data-slot="transcript-lines" className="flex flex-col">
        {groups.flatMap((group) =>
          group.segments.map((segment, i) => {
            const active = segment.id === activeId
            if (group.role === "system") {
              return (
                <p
                  key={segment.id}
                  data-slot="transcript-system"
                  className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) py-2 text-center"
                >
                  {segment.text}
                </p>
              )
            }
            return (
              <div
                key={segment.id}
                data-slot="transcript-segment"
                data-role={segment.role}
                data-active={active ? "" : undefined}
                aria-current={active ? "true" : undefined}
                className={cn(
                  "rounded-(--chatcn-radius-md) -mx-2 grid grid-cols-[auto_1fr] items-baseline gap-x-3 px-2 py-1 sm:grid-cols-[auto_5.5rem_1fr]",
                  "transition-colors duration-150",
                  active && "bg-(color:--chatcn-fill)",
                  i === 0 && "not-first:mt-2",
                )}
              >
                <span className="w-10">
                  {showTimestamps && segment.at !== undefined ? (
                    <Timestamp ms={segment.at} speaker={group.speaker} onSeek={onSeek} />
                  ) : null}
                </span>
                <span
                  title={group.speaker}
                  className={cn(
                    "text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) truncate leading-[22px] font-medium max-sm:col-start-2",
                    i > 0 && "max-sm:hidden sm:invisible",
                  )}
                >
                  {group.speaker}
                </span>
                <p
                  className={cn(
                    "text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0 leading-[22px] text-pretty [overflow-wrap:anywhere] max-sm:col-start-2",
                    active || segment.role === "user" ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-muted)",
                  )}
                >
                  <SegmentText segment={segment} />
                </p>
              </div>
            )
          }),
        )}
      </div>
    )
  }

  return (
    <>
      {groups.map((group) => {
        if (group.role === "system") {
          const segment = group.segments[0] as TranscriptSegment
          return (
            <div
              key={group.key}
              data-slot="transcript-system"
              className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex items-center gap-3 text-center"
            >
              <span aria-hidden="true" className="bg-(color:--chatcn-border) h-px flex-1" />
              <span>
                {segment.text}
                {showTimestamps && segment.at !== undefined ? (
                  <span className="tabular-nums"> · {formatTime(segment.at)}</span>
                ) : null}
              </span>
              <span aria-hidden="true" className="bg-(color:--chatcn-border) h-px flex-1" />
            </div>
          )
        }
        const first = group.segments[0] as TranscriptSegment
        return (
          <section
            key={group.key}
            data-slot="transcript-group"
            data-role={group.role}
            aria-label={group.speaker}
            className="flex flex-col gap-1"
          >
            <header className="flex h-5 items-baseline gap-2">
              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) font-medium">
                {group.speaker}
              </span>
              {showTimestamps && first.at !== undefined ? (
                <Timestamp ms={first.at} speaker={group.speaker} onSeek={onSeek} />
              ) : null}
            </header>
            <div className="flex flex-col gap-2">
              {group.segments.map((segment) => {
                const active = segment.id === activeId
                return (
                  <p
                    key={segment.id}
                    data-slot="transcript-segment"
                    data-role={segment.role}
                    data-active={active ? "" : undefined}
                    aria-current={active ? "true" : undefined}
                    className={cn(
                      "text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) max-w-[68ch] text-pretty [overflow-wrap:anywhere]",
                      "rounded-(--chatcn-radius-sm) -mx-2 px-2 transition-colors duration-150",
                      active && "bg-(color:--chatcn-fill)",
                    )}
                  >
                    <SegmentText segment={segment} />
                  </p>
                )
              })}
            </div>
          </section>
        )
      })}
    </>
  )
}

/**
 * Stick-to-bottom scrolling for chat transcripts.
 *
 * - Follows growing content only while the reader is within `threshold` px of the bottom.
 * - Any upward wheel, touch, key or scrollbar drag releases it in the same event. It never fights.
 * - Scrolling back down into the threshold, or calling `scrollToBottom`, re-engages it.
 * - A new user turn scrolls near the top of the viewport, with a spacer below it so the reply
 *   streams into empty space instead of pushing the turn away (`anchor`).
 * - Content inserted above the viewport keeps the reading position (native `overflow-anchor`,
 *   with a manual fallback for engines without it).
 * - A ResizeObserver follows content that grows after render: images, code blocks, tool output.
 * - Follows with a critically damped chase, not a fixed-duration tween, because streamed content
 *   grows at unpredictable rates. Instant under reduced motion.
 */

/** Options for `useChatcnStickToBottom`. */
interface UseChatcnStickToBottomOptions {
  /** Distance from the bottom, in px, that still counts as at the bottom. Defaults to 64. */
  threshold?: number
  /**
   * Scroll each new user turn near the top of the viewport. `true` matches
   * `[data-slot="message"][data-role="user"]`; pass a selector to match something else, or
   * `false` to always stick to the bottom instead. Defaults to true.
   */
  anchor?: boolean | string
  /** Space kept above an anchored turn, in px. Defaults to 24. */
  anchorOffset?: number
  /** Start at the bottom on mount. Defaults to true. */
  initial?: boolean
}

/* -------------------------------------------------------------------------------------------------
 * Conversation
 * -----------------------------------------------------------------------------------------------*/

interface ConversationProps extends React.ComponentProps<"div">, UseChatcnStickToBottomOptions {}

/** Scroll behavior for imperative calls. `smooth` falls back to instant under reduced motion. */
type ChatcnScrollBehavior = "smooth" | "instant"

/** Return value of `useChatcnStickToBottom`. */
interface ChatcnStickToBottom {
  /** Attach to the scrolling element. */
  scrollRef: (element: HTMLElement | null) => void
  /** Attach to the element that wraps the messages (its size is observed). */
  contentRef: (element: HTMLElement | null) => void
  /** Attach to an empty element placed after the content, inside the scroller. */
  spacerRef: (element: HTMLElement | null) => void
  /** Within `threshold` px of the bottom. */
  isAtBottom: boolean
  /** Following new content. False from the first upward scroll until the reader returns. */
  isSticky: boolean
  /** More than one viewport away from the bottom. */
  isFar: boolean
  /** Messages that arrived below while the reader was scrolled up. Resets at the bottom. */
  unread: number
  /** Scroll to the bottom and stick again. */
  scrollToBottom: (options?: { behavior?: ChatcnScrollBehavior }) => void
  /** Scroll an element near the top of the viewport, keeping room below it for a reply. */
  scrollToTurn: (element: HTMLElement, options?: { behavior?: ChatcnScrollBehavior }) => void
}

const prefersReducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches

/** True when a nested element between `target` and `root` can still scroll in `dy`'s direction. */
function nestedCanScroll(target: EventTarget | null, root: HTMLElement, dy: number) {
  let node = target instanceof Element ? target : null
  while (node && node !== root) {
    if (node instanceof HTMLElement && node.scrollHeight > node.clientHeight) {
      const overflow = getComputedStyle(node).overflowY
      if (overflow === "auto" || overflow === "scroll") {
        if (dy < 0 && node.scrollTop > 0) return true
        if (dy > 0 && node.scrollTop + node.clientHeight < node.scrollHeight - 1) return true
      }
    }
    node = node.parentElement
  }
  return false
}

function isEditable(target: EventTarget | null) {
  return (
    target instanceof HTMLElement &&
    (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))
  )
}

const UP_KEYS = new Set(["ArrowUp", "PageUp", "Home"])

const USER_TURN = '[data-slot="message"][data-role="user"]'

const MESSAGE = '[data-slot="message"]'

/** Stick-to-bottom scroll state and refs for a chat transcript. */
function useChatcnStickToBottom({
  threshold = 64,
  anchor = true,
  anchorOffset = 24,
  initial = true,
}: UseChatcnStickToBottomOptions = {}): ChatcnStickToBottom {
  const [scroller, setScroller] = React.useState<HTMLElement | null>(null)
  const [content, setContent] = React.useState<HTMLElement | null>(null)
  const spacer = React.useRef<HTMLElement | null>(null)

  const [isAtBottom, setAtBottom] = React.useState(true)
  const [isSticky, setSticky] = React.useState(true)
  const [isFar, setFar] = React.useState(false)
  const [unread, setUnread] = React.useState(0)

  // Mutable engine state. Lives in a ref so scroll handlers never re-render to read it.
  const s = React.useRef({
    sticky: true,
    /** Last scrollTop we wrote. Scroll events that land on it are ours, not the reader's. */
    written: -1,
    lastTop: 0,
    lastHeight: 0,
    raf: 0,
    target: null as null | (() => number),
    anchorEl: null as HTMLElement | null,
    mounted: false,
    unread: 0,
    touchY: 0,
    /** Manual scroll anchoring for engines without `overflow-anchor`. */
    keep: null as null | { node: Element; top: number },
  }).current

  const options = React.useRef({ threshold, anchor, anchorOffset })
  options.current = { threshold, anchor, anchorOffset }

  // Imperative helpers are created once per scroller and kept in a ref so the public functions
  // stay referentially stable.
  const api = React.useRef<{
    toBottom: (behavior?: ChatcnScrollBehavior) => void
    toTurn: (el: HTMLElement, behavior?: ChatcnScrollBehavior) => void
  } | null>(null)

  React.useEffect(() => {
    const el = scroller
    if (!el) return
    const nativeAnchoring =
      typeof CSS !== "undefined" && CSS.supports?.("overflow-anchor", "auto") === true

    const maxTop = () => Math.max(0, el.scrollHeight - el.clientHeight)
    const distance = () => maxTop() - el.scrollTop

    const write = (top: number) => {
      el.scrollTop = top
      s.written = el.scrollTop
      s.lastTop = el.scrollTop
    }

    const sync = () => {
      const d = distance()
      const atBottom = d <= options.current.threshold
      if (atBottom && s.unread) {
        s.unread = 0
        setUnread(0)
      }
      setAtBottom(atBottom)
      setFar(d > el.clientHeight)
      setSticky(s.sticky)
    }

    const stop = () => {
      if (s.raf) cancelAnimationFrame(s.raf)
      s.raf = 0
      s.target = null
    }

    const release = () => {
      stop()
      if (!s.sticky) return
      s.sticky = false
      setSticky(false)
    }

    /** Chase a moving target with exponential smoothing: fast, settles without overshoot. */
    const chase = (target: () => number, behavior: ChatcnScrollBehavior) => {
      s.target = target
      if (behavior === "instant" || prefersReducedMotion()) {
        stop()
        write(Math.min(target(), maxTop()))
        sync()
        return
      }
      if (s.raf) return
      let last = performance.now()
      const step = (now: number) => {
        const goal = s.target
        if (!goal) return
        const dt = Math.min(64, now - last)
        last = now
        const to = Math.min(goal(), maxTop())
        const from = el.scrollTop
        const gap = to - from
        if (Math.abs(gap) < 1) {
          write(to)
          s.raf = 0
          s.target = null
          sync()
          return
        }
        // Time constant of 70 ms: about 200 ms to cover most of any distance. scrollTop snaps to
        // whole pixels, so every frame moves at least one pixel or the chase would stall.
        const move = gap * (1 - Math.exp(-dt / 70))
        write(from + (Math.abs(move) < 1 ? Math.sign(gap) : move))
        s.raf = requestAnimationFrame(step)
      }
      s.raf = requestAnimationFrame(step)
    }

    const turnTop = (turn: HTMLElement) =>
      turn.getBoundingClientRect().top -
      el.getBoundingClientRect().top +
      el.scrollTop -
      options.current.anchorOffset

    /** Size the spacer so the anchored turn can reach the top while its reply is short. */
    const fitSpacer = () => {
      const pad = spacer.current
      if (!pad) return
      const turn = s.anchorEl
      if (!turn?.isConnected || !content) {
        s.anchorEl = null
        if (pad.style.height !== "0px") pad.style.height = "0px"
        return
      }
      const box = el.getBoundingClientRect()
      const contentBottom = content.getBoundingClientRect().bottom - box.top + el.scrollTop
      const need = Math.max(0, Math.ceil(turnTop(turn) + el.clientHeight - contentBottom))
      pad.style.height = `${need}px`
      // Once the reply fills the viewport the spacer is no longer needed.
      if (need === 0) s.anchorEl = null
    }

    const remember = () => {
      if (nativeAnchoring || !content) return
      const top = el.getBoundingClientRect().top
      for (const child of Array.from(content.children)) {
        const r = child.getBoundingClientRect()
        if (r.bottom > top) {
          s.keep = { node: child, top: r.top - top }
          return
        }
      }
      s.keep = null
    }

    const toBottom = (behavior: ChatcnScrollBehavior = "smooth") => {
      s.sticky = true
      setSticky(true)
      chase(maxTop, behavior)
    }

    const toTurn = (turn: HTMLElement, behavior: ChatcnScrollBehavior = "smooth") => {
      s.anchorEl = turn
      fitSpacer()
      s.sticky = true
      setSticky(true)
      chase(() => turnTop(turn), behavior)
    }

    api.current = { toBottom, toTurn }

    const onScroll = () => {
      const top = el.scrollTop
      const height = el.scrollHeight
      const ours = Math.abs(top - s.written) < 1.5
      if (!ours) {
        const movedUp = top < s.lastTop - 0.5
        // Content that shrinks clamps scrollTop upward; that is not the reader scrolling.
        const clamped = distance() < 1 && height < s.lastHeight
        if (movedUp && !clamped) release()
        else if (!movedUp && distance() <= options.current.threshold && !s.sticky) {
          s.sticky = true
        }
        s.written = -1
      }
      s.lastTop = top
      s.lastHeight = height
      remember()
      sync()
    }

    const onWheel = (event: WheelEvent) => {
      if (event.deltaY < 0 && el.scrollTop > 0 && !nestedCanScroll(event.target, el, -1)) release()
    }
    const onTouchStart = (event: TouchEvent) => {
      s.touchY = event.touches[0]?.clientY ?? 0
    }
    const onTouchMove = (event: TouchEvent) => {
      const y = event.touches[0]?.clientY ?? 0
      // Finger moving down scrolls the content up.
      if (y - s.touchY > 4 && !nestedCanScroll(event.target, el, -1)) release()
      s.touchY = y
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (isEditable(event.target)) return
      if (UP_KEYS.has(event.key) || (event.key === " " && event.shiftKey)) release()
    }

    const onResize = () => {
      fitSpacer()
      if (!nativeAnchoring && !s.sticky && s.keep?.node.isConnected) {
        const now = s.keep.node.getBoundingClientRect().top - el.getBoundingClientRect().top
        const delta = now - s.keep.top
        if (Math.abs(delta) > 0.5) write(el.scrollTop + delta)
      }
      // Streamed growth is a few lines at a time and glides. A jump of more than a viewport is
      // a history load or a layout change, so it lands instantly instead of scrolling past.
      if (s.sticky && !s.target) {
        chase(maxTop, s.mounted && distance() <= el.clientHeight ? "smooth" : "instant")
      }
      // Record growth only. On a shrink the browser clamps scrollTop and fires a scroll event;
      // onScroll needs the old, larger height to recognise that clamp and keep following.
      if (el.scrollHeight > s.lastHeight) s.lastHeight = el.scrollHeight
      remember()
      sync()
    }

    const ro = new ResizeObserver(onResize)
    ro.observe(el)
    if (content) ro.observe(content)

    const mo = new MutationObserver((records) => {
      if (!content) return
      const selector =
        options.current.anchor === false
          ? null
          : typeof options.current.anchor === "string"
            ? options.current.anchor
            : USER_TURN
      let turn: HTMLElement | null = null
      let added = 0
      for (const record of records) {
        for (const node of Array.from(record.addedNodes)) {
          if (!(node instanceof HTMLElement)) continue
          const isMessage = node.matches(MESSAGE) || node.querySelector(MESSAGE)
          if (isMessage) added++
          if (!selector) continue
          const match = node.matches(selector)
            ? node
            : (node.querySelector<HTMLElement>(selector) ?? null)
          if (match) turn = match
        }
      }
      if (!s.mounted) return
      // Only a freshly sent turn anchors. A batch of many messages is history being restored,
      // and an older turn is history being prepended: neither moves the reader.
      if (turn && selector && added <= 2) {
        const all = content.querySelectorAll<HTMLElement>(selector)
        if (all[all.length - 1] === turn) {
          toTurn(turn)
          return
        }
      }
      if (added && !s.sticky) {
        s.unread += added
        setUnread(s.unread)
      }
    })
    if (content) mo.observe(content, { childList: true, subtree: true })

    el.addEventListener("scroll", onScroll, { passive: true })
    el.addEventListener("wheel", onWheel, { passive: true })
    el.addEventListener("touchstart", onTouchStart, { passive: true })
    el.addEventListener("touchmove", onTouchMove, { passive: true })
    el.addEventListener("keydown", onKeyDown)

    if (!s.mounted) {
      if (initial) write(maxTop())
      // Starting elsewhere means following only once the reader reaches the bottom.
      else s.sticky = distance() <= options.current.threshold
    }
    s.lastHeight = el.scrollHeight
    remember()
    sync()
    // Messages present at mount never anchor and never count as unread.
    const ready = requestAnimationFrame(() => {
      s.mounted = true
    })

    return () => {
      cancelAnimationFrame(ready)
      stop()
      ro.disconnect()
      mo.disconnect()
      el.removeEventListener("scroll", onScroll)
      el.removeEventListener("wheel", onWheel)
      el.removeEventListener("touchstart", onTouchStart)
      el.removeEventListener("touchmove", onTouchMove)
      el.removeEventListener("keydown", onKeyDown)
    }
  }, [scroller, content, initial, s])

  const scrollToBottom = React.useCallback(
    (opts?: { behavior?: ChatcnScrollBehavior }) => api.current?.toBottom(opts?.behavior),
    [],
  )
  const scrollToTurn = React.useCallback(
    (element: HTMLElement, opts?: { behavior?: ChatcnScrollBehavior }) =>
      api.current?.toTurn(element, opts?.behavior),
    [],
  )
  const spacerRef = React.useCallback((element: HTMLElement | null) => {
    spacer.current = element
  }, [])

  return {
    scrollRef: setScroller,
    contentRef: setContent,
    spacerRef,
    isAtBottom,
    isSticky,
    isFar,
    unread,
    scrollToBottom,
    scrollToTurn,
  }
}

/* -------------------------------------------------------------------------------------------------
 * Context
 * -----------------------------------------------------------------------------------------------*/

interface ConversationContextValue {
  scrollRef: (element: HTMLElement | null) => void
  contentRef: (element: HTMLElement | null) => void
  spacerRef: (element: HTMLElement | null) => void
  /** Within the threshold of the bottom. */
  isAtBottom: boolean
  /** Following new content. */
  isSticky: boolean
  /** More than one viewport from the bottom. */
  isFar: boolean
  /** Messages that arrived below while the reader was scrolled up. */
  unread: number
  scrollToBottom: (options?: { behavior?: ChatcnScrollBehavior }) => void
  scrollToTurn: (element: HTMLElement, options?: { behavior?: ChatcnScrollBehavior }) => void
  /** Read text to screen readers through the conversation's polite live region. */
  announce: (text: string) => void
  /** False during the first render, so restored history does not animate in. */
  ready: boolean
}

const ConversationContext = React.createContext<ConversationContextValue | null>(null)

/**
 * The thread. Owns stick-to-bottom scrolling, the reply anchor and the live region.
 * Give it a height (or put it in a flex column) and place `ConversationContent` and
 * `ScrollToBottom` inside.
 */
function Conversation({
  threshold,
  anchor,
  anchorOffset,
  initial,
  className,
  children,
  ...props
}: ConversationProps) {
  const stick = useChatcnStickToBottom({ threshold, anchor, anchorOffset, initial })
  const [message, setMessage] = React.useState("")
  const [ready, setReady] = React.useState(false)
  React.useEffect(() => setReady(true), [])

  const announce = React.useCallback((text: string) => {
    // Clearing first makes repeated identical text announce again.
    setMessage("")
    requestAnimationFrame(() => setMessage(text))
  }, [])

  const value = React.useMemo<ConversationContextValue>(
    () => ({ ...stick, announce, ready }),
    [stick, announce, ready],
  )

  return (
    <ConversationContext.Provider value={value}>
      <div
        data-slot="conversation"
        data-at-bottom={stick.isAtBottom ? "" : undefined}
        className={cn("relative flex min-h-0 flex-col overflow-hidden", className)}
        {...props}
      >
        {children}
        <div aria-live="polite" aria-atomic="true" className="sr-only">
          {message}
        </div>
      </div>
    </ConversationContext.Provider>
  )
}

/* -------------------------------------------------------------------------------------------------
 * ConversationContent
 * -----------------------------------------------------------------------------------------------*/

interface ConversationContentProps extends React.ComponentProps<"div"> {
  /** Class names for the scrolling viewport. `className` styles the message column. */
  viewportClassName?: string
  /** Accessible name of the transcript. */
  label?: string
}

/** Scroll state and controls of the nearest `Conversation`. Returns null outside one. */
function useConversation() {
  return React.useContext(ConversationContext)
}

/**
 * The scrolling transcript. The viewport is a focusable `log` so keyboard users can scroll it;
 * the column inside is capped at 720 px with a 24 px gap between messages.
 */
function ConversationContent({
  viewportClassName,
  label = "Conversation",
  className,
  children,
  ...props
}: ConversationContentProps) {
  const ctx = useConversation()
  if (!ctx) throw new Error("ConversationContent must be used inside Conversation.")
  return (
    <div
      ref={ctx.scrollRef}
      role="log"
      aria-label={label}
      // The log is silent: tokens are never read one by one. Finished replies are announced
      // through the conversation's live region instead.
      aria-live="off"
      // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be focusable
      tabIndex={0}
      data-slot="conversation-viewport"
      className={cn(
        "chatcn-scroll chatcn-scroll-fade min-h-0 flex-1 overflow-y-auto outline-none [overflow-anchor:auto]",
        "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
        viewportClassName,
      )}
    >
      <div
        ref={ctx.contentRef}
        data-slot="conversation-content"
        className={cn(
          "mx-auto flex w-full max-w-[720px] flex-col gap-6 px-4 pt-8 pb-6 sm:px-6",
          className,
        )}
        {...props}
      >
        {children}
      </div>
      <div
        ref={ctx.spacerRef}
        aria-hidden="true"
        data-slot="conversation-spacer"
        className="pointer-events-none shrink-0 [overflow-anchor:none]"
      />
    </div>
  )
}

/** Connects the body to the conversation's announcer. */
function FollowingBody(props: Omit<BodyProps, "announceFn">) {
  const ctx = useConversation()
  return <TranscriptBody {...props} announceFn={ctx?.announce} />
}

interface ScrollToBottomProps extends Omit<React.ComponentProps<"button">, "children"> {
  /**
   * When the pill shows. `far` waits until the reader is more than one viewport up, or until a
   * new message lands below them. `away` shows as soon as they leave the bottom. Defaults to `far`.
   */
  when?: "far" | "away"
  /** Show the unread count next to the arrow. Defaults to true. */
  showUnread?: boolean
  /** Force the pill on or off, for example to keep it hidden while a dialog is open. */
  visible?: boolean
}

const iconNode3: IconNode = [
  ["path", {"d":"m5.5 12.5 4.73 4.73a2.5 2.5 0 0 0 3.54 0l4.73-4.73"}],
  ["path", {"d":"M12 5v9"}],
]

const ArrowDownIcon: Icon = /* @__PURE__ */ createIcon("arrow-down", iconNode3)

/**
 * Jump-to-latest pill. Floats at the bottom center of the nearest `Conversation`, fades in with
 * 4 px of travel over 150 ms, and re-engages stick-to-bottom when pressed. When messages land
 * below the reader, the round arrow opens sideways into "3 new" and closes again once read.
 */
function ScrollToBottom({
  when = "far",
  showUnread = true,
  visible,
  className,
  onClick,
  ...props
}: ScrollToBottomProps) {
  const ctx = useConversation()
  if (!ctx) throw new Error("ScrollToBottom must be used inside Conversation.")
  const { isAtBottom, isFar, unread, scrollToBottom } = ctx
  const show = visible ?? (when === "away" ? !isAtBottom : isFar || (!isAtBottom && unread > 0))
  const count = showUnread && unread > 0 ? unread : 0
  // Keep the last count while the label closes, so it never collapses around an empty string.
  const [shown, setShown] = React.useState(count)
  if (count > 0 && count !== shown) setShown(count)
  const label = count
    ? `${count} new ${count === 1 ? "message" : "messages"}, scroll to latest`
    : "Scroll to latest"

  return (
    <button
      type="button"
      aria-label={label}
      aria-hidden={show ? undefined : true}
      tabIndex={show ? undefined : -1}
      data-slot="scroll-to-bottom"
      data-visible={show ? "" : undefined}
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) scrollToBottom({ behavior: "smooth" })
      }}
      className={cn(
        "chatcn-focus absolute inset-x-0 bottom-4 z-10 mx-auto flex h-8 w-fit items-center rounded-full px-2",
        "bg-(color:--chatcn-card) text-(color:--chatcn-fg-muted) shadow-(--chatcn-shadow-md) text-[0.8125rem]/[1.25rem] font-medium tabular-nums select-none",
        "hover:text-(color:--chatcn-fg) active:scale-(--chatcn-press-scale) [&_svg]:size-4 [&_svg]:shrink-0",
        // Exit is 0.75x the enter. Under reduced motion the travel goes and only the fade remains.
        "ease-(--chatcn-ease-out) transition-[opacity,translate,color,scale] duration-150",
        "pointer-coarse:after:absolute pointer-coarse:after:-inset-1.5 pointer-coarse:after:content-['']",
        show
          ? "translate-y-0 opacity-100"
          : "pointer-events-none translate-y-1 opacity-0 duration-110",
        "motion-reduce:translate-y-0 motion-reduce:transition-opacity",
        className,
      )}
      {...props}
    >
      <ArrowDownIcon aria-hidden="true" />
      {/* 0fr to 1fr: the pill widens from its center as the label opens, and nothing reflows. */}
      <span
        aria-hidden="true"
        data-slot="scroll-to-bottom-count"
        data-open={count ? "" : undefined}
        className={cn(
          "grid grid-cols-[0fr] opacity-0 data-[open]:grid-cols-[1fr] data-[open]:opacity-100",
          "ease-(--chatcn-ease-out) transition-[grid-template-columns,opacity] duration-200",
          "motion-reduce:transition-opacity",
        )}
      >
        <span className="overflow-hidden whitespace-nowrap">
          <span className="ps-1.5 pe-1">{shown > 99 ? "99+" : shown} new</span>
        </span>
      </span>
    </button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Transcript
 * -----------------------------------------------------------------------------------------------*/

/**
 * Live voice transcript. Groups consecutive lines by speaker, shows unsettled words in a lighter
 * gray, marks typed lines with a keyboard glyph and cuts interrupted replies at the exact point
 * the user spoke over them. Follows new speech while you are at the bottom and lets go the moment
 * you scroll up. Timestamps become seek buttons when `onSeek` is set.
 */
export function Transcript({
  segments,
  userLabel = "You",
  assistantLabel = "Assistant",
  follow = true,
  onSeek,
  activeId,
  showTimestamps = true,
  layout = "stacked",
  empty,
  label = "Transcript",
  announce = true,
  className,
  ...props
}: TranscriptProps) {
  const groups = React.useMemo(
    () => groupSegments(segments, { user: userLabel, assistant: assistantLabel }),
    [segments, userLabel, assistantLabel],
  )
  const contentClass = cn(
    "max-w-none px-4 sm:px-5",
    layout === "inline" ? "gap-0 py-3" : "gap-5 py-4",
    segments.length === 0 && "min-h-full",
  )

  // Playback: keep the active line in view. Instant under reduced motion.
  const staticRef = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    if (follow || !activeId) return
    const root = staticRef.current
    const el = root?.querySelector<HTMLElement>(`[data-active]`)
    if (!root || !el) return
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    // Scroll the transcript only. scrollIntoView would also move the page while it plays.
    const box = root.getBoundingClientRect()
    const line = el.getBoundingClientRect()
    const delta =
      line.top < box.top
        ? line.top - box.top
        : line.bottom > box.bottom
          ? line.bottom - box.bottom
          : 0
    if (delta) root.scrollBy({ top: delta, behavior: reduced ? "auto" : "smooth" })
  }, [activeId, follow])

  // Static scrolling: mark which edges hide lines, so they fade instead of cutting a line in half.
  React.useLayoutEffect(() => {
    const el = staticRef.current
    if (follow || !el) return
    const update = () => {
      el.toggleAttribute("data-scroll-top", el.scrollTop > 1)
      el.toggleAttribute("data-scroll-bottom", el.scrollTop + el.clientHeight < el.scrollHeight - 1)
    }
    update()
    el.addEventListener("scroll", update, { passive: true })
    const observer = new ResizeObserver(update)
    observer.observe(el)
    if (el.firstElementChild) observer.observe(el.firstElementChild)
    return () => {
      el.removeEventListener("scroll", update)
      observer.disconnect()
    }
  }, [follow])

  const body = {
    segments,
    groups,
    layout,
    showTimestamps,
    onSeek,
    activeId,
    empty,
    announce,
  }

  if (!follow) {
    return (
      <div
        data-slot="transcript"
        data-layout={layout}
        className={cn("relative flex min-h-0 flex-1 flex-col overflow-hidden", className)}
        {...props}
      >
        <div
          ref={staticRef}
          role="log"
          aria-label={label}
          aria-live="off"
          // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be focusable
          tabIndex={0}
          className={cn(
            "chatcn-scroll min-h-0 flex-1 overflow-y-auto outline-none",
            "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
            "[--edge-bottom:black] [--edge-top:black] [--fade-bottom:0px] [--fade-top:0px]",
            "data-[scroll-top]:[--edge-top:transparent] data-[scroll-top]:[--fade-top:1.5rem]",
            "data-[scroll-bottom]:[--edge-bottom:transparent] data-[scroll-bottom]:[--fade-bottom:2rem]",
            "[mask-image:linear-gradient(to_bottom,var(--edge-top),black_var(--fade-top),black_calc(100%-var(--fade-bottom)),var(--edge-bottom))]",
            // Keyboard scrolling reads every line at full strength.
            "focus-visible:[mask-image:none]",
          )}
        >
          <div className={cn("flex flex-col", contentClass)}>
            <TranscriptBody {...body} />
          </div>
        </div>
      </div>
    )
  }

  return (
    <Conversation
      anchor={false}
      data-slot="transcript"
      data-layout={layout}
      className={cn("min-h-0 flex-1", className)}
      {...props}
    >
      <ConversationContent label={label} className={contentClass}>
        <FollowingBody {...body} />
      </ConversationContent>
      <ScrollToBottom when="away" showUnread={false} />
    </Conversation>
  )
}

