type AudioPlayerStatus = "loading" | "ready" | "buffering" | "error"

interface AudioPlayerProps
  extends Omit<React.ComponentProps<"div">, "title" | "onError" | "onEnded"> {
  /** Audio URL. Plays through an internal `<audio>`. Omit it and drive the player yourself. */
  src?: string
  /** One line above the track, for example the first words of the message. */
  title?: React.ReactNode
  /** Quiet detail next to the title, for example the voice name. */
  meta?: React.ReactNode
  /** `default` is a self-contained player. `compact` is a mini player for message actions. */
  variant?: "default" | "compact"
  playing?: boolean
  defaultPlaying?: boolean
  onPlayingChange?: (playing: boolean) => void
  /** Position in seconds. Controlled; pair with `onSeek`. */
  currentTime?: number
  /** Called with the new position in seconds when the user scrubs, skips or uses the keys. */
  onSeek?: (seconds: number) => void
  /** Length in seconds. Read from the file when `src` is set. */
  duration?: number
  playbackRate?: number
  defaultPlaybackRate?: number
  onPlaybackRateChange?: (rate: number) => void
  /** Speeds offered in the menu. Default 0.75, 1, 1.25, 1.5 and 2. */
  rates?: number[]
  /**
   * `loading` while speech is generated or the file loads, `buffering` while playback stalls,
   * `error` when it failed. Derived from the audio element when `src` is set.
   */
  status?: AudioPlayerStatus
  /** Shown on `error`. Say how to fix it. */
  errorText?: React.ReactNode
  /** Shows Retry on `error`. */
  onRetry?: () => void
  /** Peak levels from 0 to 1. Draws the track as a waveform instead of a line. */
  peaks?: number[]
  /** Seconds the skip back button jumps. `false` hides it. Default 10. Not in `compact`. */
  skip?: number | false
  onEnded?: () => void
  /** Accessible name of the player. Default "Audio player". */
  label?: string
}

/** Controlled when the prop is set, internal state otherwise. */
function useControllable<T>(prop: T | undefined, initial: T, onChange?: (value: T) => void) {
  const [state, setState] = React.useState(initial)
  const value = prop !== undefined ? prop : state
  const set = React.useCallback(
    (next: T) => {
      if (prop === undefined) setState(next)
      onChange?.(next)
    },
    [prop, onChange],
  )
  return [value, set] as const
}

