/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function formatTime(seconds: number) {
  const total = Math.max(0, Math.floor(Number.isFinite(seconds) ? seconds : 0))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = String(total % 60).padStart(2, "0")
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${s}` : `${m}:${s}`
}

/* -------------------------------------------------------------------------------------------------
 * Scrubber
 * -----------------------------------------------------------------------------------------------*/

interface ScrubberProps {
  value: number
  duration: number
  disabled: boolean
  peaks?: number[]
  compact: boolean
  onSeek: (seconds: number) => void
  onToggle: () => void
}

function spokenDuration(seconds: number) {
  const total = Math.max(0, Math.round(seconds))
  const m = Math.floor(total / 60)
  const s = total % 60
  const parts: string[] = []
  if (m) parts.push(`${m} ${m === 1 ? "minute" : "minutes"}`)
  if (s || !m) parts.push(`${s} ${s === 1 ? "second" : "seconds"}`)
  return parts.join(" ")
}

/** Narrowest bar plus gap, in px. Below this the bars would run into each other. */
const BAR_PITCH = 3

/** Down-samples peaks to `n` bars, keeping each bucket's loudest value so no syllable is lost. */
function fitPeaks(peaks: number[], n: number) {
  if (n <= 0 || n >= peaks.length) return peaks
  const out: number[] = []
  for (let i = 0; i < n; i++) {
    const from = Math.floor((i * peaks.length) / n)
    const to = Math.max(from + 1, Math.floor(((i + 1) * peaks.length) / n))
    let max = 0
    for (let j = from; j < to; j++) max = Math.max(max, peaks[j] ?? 0)
    out.push(max)
  }
  return out
}

/**
 * A static waveform: dim bars, with the played part drawn over them in ink and clipped. The bar
 * count follows the width it has, so a narrow player draws fewer bars instead of overflowing.
 */
function Peaks({ peaks, pct }: { peaks: number[]; pct: string }) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [fit, setFit] = React.useState(peaks.length)
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    const measure = () => setFit(Math.max(8, Math.floor((el.clientWidth + 2) / BAR_PITCH)))
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    return () => observer.disconnect()
  }, [])
  const shown = React.useMemo(() => fitPeaks(peaks, fit), [peaks, fit])
  const bars = (tone: string) => (
    <div className="flex h-full w-full items-center gap-[2px]">
      {shown.map((p, i) => (
        <span
          key={i}
          style={{ height: `${Math.max(12, Math.min(1, Math.max(0, p)) * 100)}%` }}
          className={cn("min-w-px flex-1 rounded-full", tone)}
        />
      ))}
    </div>
  )
  return (
    <div
      ref={ref}
      data-slot="audio-player-peaks"
      className="relative h-full w-full min-w-0 overflow-hidden py-1"
    >
      <div className="h-full">{bars("bg-(color:--chatcn-border-strong)")}</div>
      <div
        style={{ "--p": pct } as React.CSSProperties}
        className="absolute inset-0 py-1 [clip-path:inset(0_calc(100%-var(--p))_0_0)] rtl:[clip-path:inset(0_0_0_calc(100%-var(--p)))]"
      >
        {bars("bg-(color:--chatcn-fg)")}
      </div>
    </div>
  )
}

/**
 * The seek bar: a real `slider` with keyboard steps, pointer capture for dragging and a time
 * preview under the pointer. Progress moves with transforms only.
 */
function Scrubber({ value, duration, disabled, peaks, compact, onSeek, onToggle }: ScrubberProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [drag, setDrag] = React.useState<number>()
  const [hover, setHover] = React.useState<{ x: number; t: number }>()
  const shown = drag ?? value
  const ratio = duration > 0 ? Math.min(1, Math.max(0, shown / duration)) : 0
  const pct = `${(ratio * 100).toFixed(3)}%`

  const timeAt = (clientX: number) => {
    const el = ref.current
    if (!el || duration <= 0) return { t: 0, x: 0 }
    const rect = el.getBoundingClientRect()
    const rtl = getComputedStyle(el).direction === "rtl"
    const x = Math.min(rect.width, Math.max(0, clientX - rect.left))
    const r = rect.width > 0 ? x / rect.width : 0
    return { t: (rtl ? 1 - r : r) * duration, x }
  }

  const seek = (t: number) => onSeek(Math.min(duration, Math.max(0, t)))

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const fwd = rtl ? "ArrowLeft" : "ArrowRight"
    const back = rtl ? "ArrowRight" : "ArrowLeft"
    let next: number | undefined
    if (event.key === fwd || event.key === "ArrowUp") next = value + 5
    else if (event.key === back || event.key === "ArrowDown") next = value - 5
    else if (event.key === "PageUp" || event.key === "l")
      next = value + (event.key === "l" ? 10 : 30)
    else if (event.key === "PageDown" || event.key === "j")
      next = value - (event.key === "j" ? 10 : 30)
    else if (event.key === "Home") next = 0
    else if (event.key === "End") next = duration
    else if (event.key === " " || event.key === "k") {
      event.preventDefault()
      onToggle()
      return
    }
    if (next === undefined) return
    event.preventDefault()
    seek(next)
  }

  return (
    <div
      ref={ref}
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-label="Seek"
      aria-valuemin={0}
      aria-valuemax={Math.round(duration)}
      aria-valuenow={Math.round(shown)}
      aria-valuetext={`${spokenDuration(shown)} of ${spokenDuration(duration)}`}
      aria-disabled={disabled || undefined}
      data-slot="audio-player-scrubber"
      data-dragging={drag !== undefined ? "" : undefined}
      onKeyDown={onKeyDown}
      onPointerDown={(event) => {
        if (disabled || event.button !== 0) return
        event.currentTarget.setPointerCapture(event.pointerId)
        const { t } = timeAt(event.clientX)
        setDrag(t)
        seek(t)
      }}
      onPointerMove={(event) => {
        if (disabled) return
        const { t, x } = timeAt(event.clientX)
        if (event.pointerType === "mouse") setHover({ x, t })
        if (drag !== undefined) {
          setDrag(t)
          seek(t)
        }
      }}
      onPointerUp={() => setDrag(undefined)}
      onPointerCancel={() => setDrag(undefined)}
      onPointerLeave={() => setHover(undefined)}
      className={cn(
        "group/scrub chatcn-focus rounded-(--chatcn-radius-xs) relative flex min-w-0 flex-1 cursor-pointer touch-none items-center select-none",
        peaks ? "h-8" : compact ? "h-5" : "h-6",
        "pointer-coarse:h-11",
        disabled && "pointer-events-none cursor-default opacity-50",
      )}
    >
      {peaks && peaks.length > 0 ? (
        <Peaks peaks={peaks} pct={pct} />
      ) : (
        <div
          className={cn(
            "bg-(color:--chatcn-fill-active) relative w-full overflow-hidden rounded-full",
            compact ? "h-[3px]" : "h-1",
          )}
        >
          <div
            style={{ transform: `scaleX(${ratio})` }}
            className="bg-(color:--chatcn-accent) absolute inset-0 origin-left rounded-full rtl:origin-right"
          />
        </div>
      )}
      {/* Thumb. Full-width wrapper so a percentage translate lands on the track position. */}
      {peaks ? null : (
        <div
          aria-hidden="true"
          style={{ "--x": pct } as React.CSSProperties}
          className="pointer-events-none absolute inset-0 translate-x-(--x) rtl:-translate-x-(--x)"
        >
          <span
            className={cn(
              "bg-(color:--chatcn-accent) shadow-(--chatcn-shadow-xs) absolute start-0 top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full rtl:translate-x-1/2",
              "opacity-0 transition-opacity duration-150",
              "group-hover/scrub:opacity-100 group-focus-visible/scrub:opacity-100 group-data-[dragging]/scrub:opacity-100",
              "pointer-coarse:opacity-100",
            )}
          />
        </div>
      )}
      {hover && !compact ? (
        <span
          aria-hidden="true"
          style={{ transform: `translateX(${hover.x}px) translateX(-50%)` }}
          // The offset is measured in physical pixels from the left edge, so this stays physical.
          className="bg-(color:--chatcn-fg) text-(color:--chatcn-bg) text-[0.75rem]/[1rem] rounded-(--chatcn-radius-xs) pointer-events-none absolute bottom-full left-0 mb-1 px-1.5 py-0.5 font-medium whitespace-nowrap tabular-nums"
        >
          {formatTime(hover.t)}
        </span>
      ) : null}
    </div>
  )
}

