/**
 * Read-aloud and audio output player. Play and pause in one round button, a seek bar you can drag
 * or step with the keys, the time in tabular figures and a speed menu. Plays a `src` itself, or
 * takes `playing`, `currentTime` and `duration` from a speech engine that has no file.
 */
function AudioPlayer({
  src,
  title,
  meta,
  variant = "default",
  playing: playingProp,
  defaultPlaying = false,
  onPlayingChange,
  currentTime: timeProp,
  onSeek,
  duration: durationProp,
  playbackRate: rateProp,
  defaultPlaybackRate = 1,
  onPlaybackRateChange,
  rates = DEFAULT_RATES,
  status: statusProp,
  errorText,
  onRetry,
  peaks,
  skip = 10,
  onEnded,
  label = "Audio player",
  className,
  ...props
}: AudioPlayerProps) {
  const audio = React.useRef<HTMLAudioElement>(null)
  const [playing, setPlaying] = useControllable(playingProp, defaultPlaying, onPlayingChange)
  const [rate, setRate] = useControllable(rateProp, defaultPlaybackRate, onPlaybackRateChange)
  const [mediaTime, setMediaTime] = React.useState(0)
  const [mediaDuration, setMediaDuration] = React.useState(0)
  const [mediaStatus, setMediaStatus] = React.useState<AudioPlayerStatus>(src ? "loading" : "ready")
