    if (busy || status === "error") return
    setInstant(via === "keyboard")
    if (ended && !playing) seek(0)
    setPlaying(!playing)
  }

  const glyph = busy ? (
    <Spinner className={compact ? "size-3" : "size-4"} />
  ) : ended ? (
    <RotateCcwIcon />
  ) : playing ? (
    <PauseIcon className="fill-current" />
  ) : (
    <PlayIcon className="fill-current ltr:translate-x-px rtl:-translate-x-px rtl:-scale-x-100" />
  )
  const glyphKey = busy ? "busy" : ended ? "ended" : playing ? "pause" : "play"
  const playLabel = busy ? "Preparing audio" : ended ? "Play again" : playing ? "Pause" : "Play"

  const playButton = (
    <button
      type="button"
      aria-label={playLabel}
      aria-disabled={busy || status === "error" || undefined}
      data-slot="audio-player-toggle"
      onClick={(event) => toggle(event.detail === 0 ? "keyboard" : "pointer")}
      className={cn(
        "chatcn-focus relative grid shrink-0 place-items-center rounded-full",
        "bg-(color:--chatcn-fg) text-(color:--chatcn-bg) hover:bg-(color:--chatcn-gray-900) transition-[background-color,scale] duration-150",
        "active:scale-(--chatcn-press-scale-icon) active:duration-100",
        compact ? "size-6 [&_svg]:size-3" : "size-10 [&_svg]:size-4",
        compact
          ? "pointer-coarse:after:absolute pointer-coarse:after:-inset-2.5 pointer-coarse:after:content-['']"
          : "pointer-coarse:size-11",
        (busy || status === "error") && "hover:bg-(color:--chatcn-fg) cursor-default",
        status === "error" && "opacity-50",
      )}
    >
      <span
        key={glyphKey}
        className={cn(
          "grid place-items-center",
          !instant && "motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]",
        )}
      >
        {glyph}
      </span>
      {status === "buffering" && playing ? (
        <span
          aria-hidden="true"
          className="pointer-events-none absolute -inset-[3px] grid place-items-center"
        >
          <Spinner className="text-(color:--chatcn-fg-subtle) size-full" />
        </span>
      ) : null}
    </button>
  )

  const timeText =
    busy && duration <= 0 ? (
      <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) whitespace-nowrap">
        Preparing audio
      </span>
    ) : (
      <span
        data-slot="audio-player-time"
        // Times read left to right in every language: "0:18 / 2:40", never "2:40 / 0:18".
        dir="ltr"
        className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 whitespace-nowrap tabular-nums"
      >
        <span className="text-(color:--chatcn-fg-muted)">{formatTime(time)}</span>
        <span aria-hidden="true"> / </span>
        <span className="sr-only"> of </span>
        {formatTime(duration)}
      </span>
    )

  const scrubber = (
    <Scrubber
      value={time}
      duration={duration}
      disabled={busy || status === "error" || duration <= 0}
      peaks={peaks}
      compact={compact}
      onSeek={seek}
      onToggle={() => toggle("keyboard")}
    />
  )

  const error = (
    <div
      role="alert"
      data-slot="audio-player-error"
      className="flex min-w-0 flex-1 items-center gap-2"
    >
      <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-4 shrink-0" />
      <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) min-w-0 flex-1 text-pretty">
        {errorText ?? "The audio could not load. Check your connection, then retry."}
      </span>
      {onRetry ? (
        <Button size="xs" variant="outline" onClick={onRetry}>
          <RotateCcwIcon />
          Retry
        </Button>
      ) : null}
    </div>
  )

  const element = src ? (
    // biome-ignore lint/a11y/useMediaCaption: speech output; the message text is the caption
    <audio
      ref={audio}
      src={src}
      preload="metadata"
      onLoadedMetadata={(event) => {
        setMediaDuration(event.currentTarget.duration)
