      // biome-ignore lint/a11y/useSemanticElements: a fieldset would bring form semantics to a player
      <div
        role="group"
        aria-label={label}
        data-slot="audio-player"
        data-variant="compact"
        data-audio-state={status === "ready" ? (playing ? "playing" : "paused") : status}
        className={cn(
          "bg-(color:--chatcn-fill) inline-flex h-8 max-w-full min-w-0 items-center gap-2.5 rounded-full ps-1 pe-3",
          className,
        )}
        {...props}
      >
        {element}
        {playButton}
        {status === "error" ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) flex items-center gap-1.5">
            <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-3.5" />
            {errorText ?? "Audio unavailable"}
            {onRetry ? (
              <button
                type="button"
                onClick={onRetry}
                className="chatcn-focus text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) font-medium underline-offset-2 hover:underline"
              >
                Retry
