    // biome-ignore lint/a11y/useSemanticElements: a fieldset would bring form semantics to a player
    <div
      role="group"
      aria-label={label}
      data-slot="audio-player"
      data-variant="default"
      data-audio-state={status === "ready" ? (playing ? "playing" : "paused") : status}
      className={cn(
        "rounded-(--chatcn-radius-xl) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex w-full min-w-0 items-center gap-3 p-3",
        className,
      )}
      {...props}
    >
      {element}
      {playButton}
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        {title || meta ? (
          // One line tall: a meta with no room wraps onto a hidden second line instead of
          // shrinking to a single letter.
          <div className="flex h-5 min-w-0 flex-wrap items-baseline gap-x-2 overflow-hidden pe-1">
            {title ? (
              // The title keeps its width; the meta gives way first.
              <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) max-w-full shrink-0 truncate font-medium">
                {title}
              </span>
            ) : null}
            {meta ? (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) min-w-12 flex-1 basis-0 truncate">
                {meta}
              </span>
            ) : null}
          </div>
        ) : null}
        {status === "error" ? (
          <div className="flex min-h-6 items-center">{error}</div>
        ) : (
          <div className="flex min-w-0 items-center gap-3">
            {scrubber}
            {timeText}
          </div>
        )}
      </div>
      {status === "error" ? null : (
        <div className="flex shrink-0 items-center gap-0.5">
          {skip !== false ? (
            <Button
              size="icon-sm"
              aria-label={`Back ${skip} seconds`}
              disabled={busy || duration <= 0}
              onClick={() => seek(time - skip)}
              className="pointer-coarse:size-11"
            >
              <SkipBackIcon className="rtl:-scale-x-100" />
            </Button>
          ) : null}
          <Menu>
            <MenuTrigger
              render={
                <Button
                  size="sm"
                  aria-label={`Playback speed, ${formatRate(rate)}`}
                  className="min-w-11 px-2 tabular-nums pointer-coarse:h-11"
                />
              }
            >
              {formatRate(rate)}
            </MenuTrigger>
            <MenuContent align="end" className="min-w-36">
              <MenuRadioGroup
                value={String(rate)}
                onValueChange={(value) => setRate(Number(value))}
              >
                <MenuLabel>Speed</MenuLabel>
