/**
 * Playback of a finished call. The active line follows the playhead; every timestamp seeks.
 * The player and the transcript share one clock, simulated here instead of an audio file.
 */
function TranscriptPlayback() {
  const [playing, setPlaying] = React.useState(false)
  const [time, setTime] = React.useState(0)
  const [rate, setRate] = React.useState(1)

  React.useEffect(() => {
    if (!playing) return
    let last = performance.now()
    let raf = 0
    const tick = (now: number) => {
      const dt = ((now - last) / 1000) * rate
      last = now
      setTime((t) => {
        const next = t + dt
        if (next >= DURATION) {
          setPlaying(false)
          return DURATION
        }
        return next
      })
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [playing, rate])

  const activeId = React.useMemo(() => {
    let id: string | undefined
    for (const seg of SEGMENTS) if ((seg.at ?? 0) <= time * 1000) id = seg.id
    return time > 0 ? id : undefined
  }, [time])

  return (
    <div className="rounded-(--chatcn-radius-xl) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex h-[460px] w-full max-w-2xl flex-col overflow-hidden">
      <Transcript
        segments={SEGMENTS}
        layout="inline"
        follow={false}
        activeId={activeId}
        onSeek={(ms) => {
          setTime(ms / 1000)
          setPlaying(true)
        }}
        label="Incident review transcript"
      />
      <div className="border-(color:--chatcn-border) border-t p-2">
        <AudioPlayer
          title="Billing incident review"
          meta="Oct 21 · 3 speakers"
          playing={playing}
          onPlayingChange={setPlaying}
          currentTime={time}
          duration={DURATION}
          onSeek={setTime}
          playbackRate={rate}
          onPlaybackRateChange={setRate}
          className="shadow-none"
        />
      </div>
    </div>
  )
}

